    return x->price - y->price;
}

static inline int entry_less(Entry a, Entry b) {
    if (a.price != b.price) return a.price < b.price;
    return a.type < b.type;
}

void heap_init(MinHeap *h, int cap) {
    h->data = (Entry*)malloc(sizeof(Entry) * cap);
    h->size = 0;
}

void heap_push(MinHeap *h, int price, int type) {
    int i = h->size++;
    Entry e;
    e.price = price;
    e.type = type;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (entry_less(e, h->data[p])) {
            h->data[i] = h->data[p];
            i = p;
        } else {
            break;
        }
    }
    h->data[i] = e;
}

